/* Contenido de las lecciones — español */
I18N.registerLessons("es", {

/* ===================== PIANO ===================== */
"piano-1":{title:"Encuentro con las teclas",goal:"Identificar cualquier nota del piano en cinco segundos",b:{
0:"El piano impone: 88 teclas. ¿La verdad? Solo hay <b>12 teclas</b> que se repiten una y otra vez. En cuanto veas el patrón, el instrumento entero se abre.",
1:"El secreto está en las teclas negras: están agrupadas de <b>dos</b> en dos y de <b>tres</b> en tres, alternándose. Ese es tu mapa.",
2:["Busca un grupo de dos teclas negras.","La tecla blanca que queda justo a su izquierda (hacia los graves) es el <b>do (C)</b>.","A partir de ahí basta con seguir: do, re, mi, fa, sol, la, si — y otra vez do.","Cada do siguiente es el mismo sonido, solo que más agudo. Eso se llama <b>octava</b>."],
3:"Pulsa la tecla marcada: es el do (C4). Intenta encontrar también los demás do.",
4:"<b>Consejo de oro:</b> el do central (C4) está más o menos en el centro del piano, frente a la cerradura o el logotipo. Es el punto de referencia de todo pianista.",
5:"La escala de do mayor: las siete notas blancas y vuelta al do",
6:{q:"¿Cómo se localiza la nota do en el piano?",o:["La tecla blanca a la izquierda de tres negras","La tecla blanca pegada al grupo de dos negras, por el lado grave","La primera tecla negra","La tecla blanca del centro del teclado"],w:"El do es siempre la tecla blanca pegada al grupo de dos negras, por el lado de los graves."},
7:"Siéntate al teclado (real o en pantalla) y di en voz alta todos los do, y luego todos los fa. Tres minutos y listo."}},

"piano-2":{title:"La mano derecha: cinco dedos, cinco notas",goal:"Tocar do–re–mi–fa–sol seguidos sin mirarte las manos",b:{
0:"En el piano cada dedo tiene un número: <b>1 = pulgar</b>, 2 = índice, 3 = corazón, 4 = anular, 5 = meñique. La numeración es la misma en ambas manos.",
1:"Coloca el pulgar derecho sobre el <b>do (C4)</b> y cada dedo siguiente sobre la tecla blanca siguiente. Ahora tus cinco dedos están exactamente sobre do-re-mi-fa-sol. Es la «posición de do», la primera posición que aprende todo pianista.",
2:"Posición de do: dedos 1, 2, 3, 4, 5",
3:["Curva un poco los dedos, como si sostuvieras una naranja pequeña.","Mantén la muñeca recta: ni hundida ni levantada.","Toca 1-2-3-4-5 despacio, cada nota con el mismo volumen.","Ahora vuelve: 5-4-3-2-1.","Cuando fluya, cierra los ojos y tócalo otra vez."],
4:"<b>La igualdad de sonido importa más que la velocidad.</b> El dedo débil (el 4) siempre intentará sonar más flojo. Dale atención especial.",
5:"Ejercicio de dedos n.º 1",
6:{q:"¿Qué dedo es el número 1 en el piano?",o:["El meñique","El corazón","El pulgar","El índice"],w:"El pulgar es siempre el dedo número 1, en ambas manos."},
7:"Toca el ejercicio cinco veces seguidas sin fallos. Si te equivocas, empieza de nuevo más despacio."}},

"piano-3":{title:"Tu primera canción",goal:"Tocar una melodía completa de oído y leyéndola",b:{
0:"Ha llegado el momento: estás tocando una canción. «Campanita del lugar» es una melodía popular francesa del siglo XVIII (dominio público); Mozart incluso escribió variaciones sobre ella.",
1:"Todas las notas están dentro de la posición de do que aprendiste, salvo el <b>la (A4)</b>, al que llegamos desplazando ligeramente el meñique.",
2:"Campanita del lugar: la melodía completa",
3:"Las notas que necesitas para la canción",
4:["Escucha la melodía dos veces con el botón de reproducción.","Toca solo las cuatro primeras notas: do do sol sol.","Añade: la la sol (el sol es largo, dos tiempos).","Sigue: fa fa mi mi re re do.","Une todo despacio y solo después añade velocidad."],
5:"<b>La regla clave del aprendizaje autodidacta:</b> despacio = rápido. Un cerebro que aprende despacio y sin errores llega a la velocidad tres veces antes.",
6:{q:"¿A qué tempo hay que empezar una pieza nueva?",o:["Lo más rápido posible","Al tempo en el que la tocas sin errores","Al tempo original de la pieza","Da igual"],w:"El tempo correcto es aquel en el que te sale sin fallos. La velocidad llega después por sí sola."},
7:"Toca la canción tres veces seguidas sin parar."}},

"piano-4":{title:"El ritmo: el idioma del tiempo",goal:"Contar 1-2-3-4 y tocar distintas figuras",b:{
0:"La música no es solo qué notas, sino <b>cuándo</b>. Las figuras básicas:",
1:["<b>Redonda</b>: dura 4 tiempos.","<b>Blanca</b>: 2 tiempos.","<b>Negra</b>: un tiempo. Es la figura más común de todas.","<b>Corchea</b>: medio tiempo. Se cuenta 1-y-2-y."],
2:"Ejercicio de ritmo: contar a cuatro",
3:"La mayoría de las canciones populares tienen <b>cuatro tiempos por compás</b> (4/4). El primer tiempo es más fuerte: es el pulso de la canción.",
4:"Primero se palmea, después se toca. Si no consigues palmear un ritmo, tampoco conseguirás tocarlo.",
5:"La misma nota, distintas figuras",
6:{q:"¿Cuántos tiempos dura una negra en 4/4?",o:["4","2","1","Medio"],w:"Una negra = un tiempo. Cuatro negras llenan un compás completo."},
7:"Pon el metrónomo a 70 y palmea exactamente sobre los tiempos. Luego palmea corcheas (dos veces por tiempo)."}},

"piano-5":{title:"Entra la mano izquierda",goal:"Tocar un bajo sencillo con la mano izquierda",b:{
0:"La mano izquierda toca los sonidos graves: la base armónica. Empezamos sencillo: una nota por compás.",
1:"Do y sol en la octava de la mano izquierda",
2:["Coloca el meñique izquierdo sobre do (C3).","Coloca el pulgar sobre sol (G3).","Toca do y cuenta 4. Toca sol y cuenta 4.","Cuando esté firme, toca do-sol-do-sol en los tiempos 1 y 3."],
3:"La mano izquierda siempre parece «torpe» al principio. Es totalmente normal: simplemente ha entrenado menos en la vida. En una semana se pone al día.",
4:"Ejercicio de bajo",
5:{q:"¿Cuál es la función principal de la mano izquierda en el piano popular?",o:["Tocar la melodía","Tocar el bajo y la armonía","Pasar las páginas","Solo llevar el compás"],w:"La mano izquierda construye la base armónica sobre la que se apoya la melodía de la derecha."},
6:"Toca el ejercicio de bajo con el metrónomo a 70."}},

"piano-6":{title:"Las dos manos juntas: el gran momento",goal:"Coordinar las manos en un ejercicio sencillo",b:{
0:"Aquí es donde se atasca la mayoría de los autodidactas, y por un solo motivo: unen las manos demasiado pronto.",
1:["Toca la mano derecha sola hasta que sea completamente automática.","Haz lo mismo con la izquierda.","Toca un solo compás con ambas manos y para.","Añade un compás cada vez.","Si te atascas, vuelve a manos separadas. Siempre."],
2:"Ejercicio a dos manos (la melodía)",
3:"Ejercicio a dos manos (el bajo)",
4:"<b>Un truco que funciona:</b> di en voz alta las notas de la mano derecha mientras tocas. Obliga al cerebro a separar las manos.",
5:{q:"¿Qué hacer cuando no consigues unir las dos manos?",o:["Tocar más rápido","Renunciar a la mano izquierda","Volver a manos separadas y unir solo un compás","Cambiar de pieza"],w:"Dividir en trozos pequeños y reconstruir poco a poco es el único método que funciona."},
6:"Toca los dos ejercicios juntos, solo dos compases, diez veces."}},

"piano-7":{title:"Escala de do mayor y el paso del pulgar",goal:"Tocar una octava completa con una mano",b:{
0:"Solo tienes cinco dedos, y la escala tiene ocho notas. La solución es el <b>paso del pulgar</b>, el movimiento más importante de la técnica pianística.",
1:"Escala de do mayor ascendente",
2:["Mano derecha: 1-2-3 sobre do-re-mi.","Mientras el dedo 3 toca mi, el pulgar «pasa» por debajo de la palma.","El pulgar aterriza en fa, y desde ahí 1-2-3-4-5 hasta el do siguiente.","La digitación completa: 1 2 3 1 2 3 4 5.","Al bajar: 5 4 3 2 1 3 2 1."],
3:"El codo y el antebrazo deben acompañar ligeramente a la mano hacia la derecha. Si solo se mueve el pulgar, resultará torpe.",
4:"Escala de do mayor: ida y vuelta",
5:{q:"¿Cuándo pasa el pulgar bajo la palma en una escala de do mayor ascendente?",o:["Después de la nota re","Mientras el dedo 3 toca mi","Después de sol","No pasa"],w:"El paso ocurre mientras el dedo 3 toca mi, para que el pulgar llegue a tiempo a fa."},
6:"Toca la escala de ida y vuelta cuatro veces con el metrónomo a 60."}},

"piano-8":{title:"Acordes: tres notas que lo cambian todo",goal:"Tocar C, F y G con la mano izquierda",b:{
0:"Un <b>acorde</b> son tres o más notas sonando juntas. Un acorde mayor se construye saltando: nota, saltas una, nota, saltas una, nota.",
1:"Acorde de do mayor (C): do-mi-sol",
2:"Acorde de fa mayor (F): fa-la-do",
3:"Acorde de sol mayor (G): sol-si-re",
4:"Estos tres acordes (C, F, G) bastan para cientos de canciones. Son «los tres grandes» de la tonalidad.",
5:"Fíjate en que los tres se construyen igual: dedos 5-3-1 de la mano izquierda, sobre tecla blanca, saltas, tecla, saltas, tecla.",
6:{q:"¿De qué notas se compone el acorde de do mayor?",o:["do-re-mi","do-mi-sol","do-fa-la","do-sol-do"],w:"Un acorde mayor se construye con los grados 1.º, 3.º y 5.º de la escala: do-mi-sol."},
7:"Alterna entre C, F y G, cuatro tiempos por acorde, con el metrónomo a 60."}},

"piano-9":{title:"El acompañamiento: tocar una canción con acordes",goal:"Combinar melodía en la derecha y acordes en la izquierda",b:{
0:"Ahora lo unimos: la mano izquierda toca un acorde y la derecha la melodía. Así se acompaña cualquier canción del mundo.",
1:["Toca «Campanita del lugar» con la mano derecha.","En el primer compás, acorde C en la mano izquierda.","Cuando la melodía llega a «la la sol», pasa a F y luego a C.","En el penúltimo compás, G, y para terminar otra vez C."],
2:"Melodía para practicar",
3:"<b>¿Cómo saber qué acorde encaja?</b> Comprueba qué acorde contiene la nota que la melodía toca en ese tiempo. Si la melodía toca mi, encajará C (do-mi-sol).",
4:{q:"¿Qué acorde contiene la nota la?",o:["C (do-mi-sol)","G (sol-si-re)","F (fa-la-do)","Ninguno"],w:"El acorde F está formado por fa-la-do, así que contiene la nota la."},
5:"Toca la canción con acompañamiento, muy despacio, dos veces."}},

"piano-10":{title:"Mayor y menor: el color emocional",goal:"Reconocer y tocar acordes menores",b:{
0:"La diferencia entre «alegre» y «triste» en música es <b>un semitono</b>. Mueve la nota central de un acorde mayor una tecla a la izquierda y tendrás un acorde menor.",
1:"Acorde de la menor (Am): la-do-mi",
2:"Acorde de re menor (Dm): re-fa-la",
3:"Acorde de mi menor (Em): mi-sol-si",
4:"Toca C y luego Am, uno detrás de otro. Fíjate en cómo cambia al instante el estado de ánimo del sonido. Ese es el poder de la armonía.",
5:{q:"¿Cuál es la diferencia entre un acorde mayor y uno menor?",o:["El menor es más agudo","La nota central del menor está un semitono más baja","El menor tiene cuatro notas","No hay una diferencia real"],w:"La nota central (la tercera) baja un semitono, y en eso consiste toda la diferencia entre «alegre» y «triste»."},
6:"Toca la secuencia C – Am – F – G, cuatro tiempos por acorde. Es la secuencia más común de la música popular."}},

"piano-11":{title:"Dinámica, pedal y expresión",goal:"Convertir un toque técnico en un toque musical",b:{
0:"Dos personas tocarán las mismas notas y una sonará como un robot. La diferencia es la <b>dinámica</b>: el cambio de volumen al tocar.",
1:["<b>Piano (p)</b>: suave. <b>Forte (f)</b>: fuerte.","<b>Crescendo</b>: aumento gradual. <b>Diminuendo</b>: descenso gradual.","Toca la escala: empieza suave, llega al máximo en el do agudo y baja de intensidad al descender.","Una frase musical es como una frase hablada: tiene comienzo, clímax y final."],
2:"<b>El pedal derecho</b> (el de resonancia) levanta los apagadores de las cuerdas y el sonido sigue sonando. La regla: cambiar de pedal en cada cambio de acorde; si no, se crea un «barro» sonoro.",
3:"La técnica correcta: se pisa el pedal <b>justo después</b> de que el dedo haya tocado, no antes. Se llama «pedal retardado».",
4:{q:"¿Cuándo se cambia el pedal?",o:["En cada nota","En cada cambio de acorde","Solo al final de la pieza","Nunca, se mantiene pisado"],w:"Cambiar el pedal en cada cambio de acorde mantiene el sonido limpio."},
5:"Toca la escala con crescendo al subir y diminuendo al bajar."}},

"piano-12":{title:"Pieza final: Himno a la alegría",goal:"Tocar una obra clásica completa",b:{
0:"Has terminado el itinerario básico. Es hora de tocar una obra de verdad: el tema de la Novena sinfonía de Beethoven (1824), de dominio público.",
1:"Himno a la alegría",
2:["Toca la mano derecha sola, de cuatro en cuatro compases.","Añade un bajo sencillo en la izquierda: C – C – G – C.","Añade dinámica: comienzo tranquilo, clímax en el centro.","Añade pedal en los cambios de acorde.","Toca de principio a fin sin parar, aunque te equivoques."],
3:"<b>La regla del intérprete experimentado:</b> en la interpretación no se para a corregir. Se sigue. Las correcciones pertenecen al estudio, no a la interpretación.",
4:{q:"¿Cuál es la forma más eficaz de estudiar una pieza nueva?",o:["Tocarla entera una y otra vez","Aislar los pasajes difíciles y trabajar solo esos","Tocar solo las partes fáciles","Limitarse a escuchar grabaciones"],w:"El trabajo focalizado en los pasajes difíciles ahorra horas. El 80 % del tiempo debe ir al 20 % más difícil."},
5:"Grábate tocando (con el móvil) y escúchalo. Oirás cosas que no notaste mientras tocabas."}},

/* ===================== GUITARRA ===================== */
"guitar-1":{title:"Encuentro con la guitarra y la postura correcta",goal:"Sentarse bien, sujetar bien y afinar la guitarra",b:{
0:"La guitarra tiene seis cuerdas. La más gruesa (arriba) es el <b>mi grave (E)</b> y la más fina (abajo) el <b>mi agudo (E)</b>. La numeración va <b>de la fina a la gruesa</b>: la más fina es la cuerda 1.",
1:["Cuerda 6: mi grave (E2)","Cuerda 5: la (A2)","Cuerda 4: re (D3)","Cuerda 3: sol (G3)","Cuerda 2: si (B3)","Cuerda 1: mi agudo (E4)"],
2:"El sonido de las cuerdas al aire, de la gruesa a la fina",
3:"<b>Sentarse correctamente:</b> espalda recta, caja de la guitarra sobre la pierna derecha (para diestros), mástil ligeramente elevado. Pulgar de la mano izquierda detrás del mástil, sin asomar por arriba.",
4:"Que duelan las yemas las dos primeras semanas es normal: la piel se endurece. El dolor en la muñeca o el hombro <b>no</b> es normal e indica una postura equivocada. Para y corrige la posición.",
5:"Afina la guitarra antes de cada sesión. Una guitarra desafinada enseña a tu oído sonidos incorrectos. Usa el <a href='#/tools/tuner'>afinador de la aplicación</a>.",
6:{q:"¿Qué cuerda es la número 1?",o:["La más gruesa","La más fina","La del medio","Depende de la guitarra"],w:"La cuerda 1 es la más fina, el mi agudo."},
7:"Afina la guitarra y luego toca cada cuerda al aire diciendo su nombre en voz alta."}},

"guitar-2":{title:"La mano derecha: tu primer rasgueo",goal:"Producir un sonido limpio y uniforme al aire",b:{
0:"La mano derecha se encarga del sonido y del ritmo. Se puede tocar con púa o con los dedos; empezaremos con púa.",
1:["Sujeta la púa entre el pulgar y el índice, dejando solo 3–5 mm por fuera.","El movimiento sale de la muñeca, no del codo.","Rasguea hacia abajo por las seis cuerdas: un solo sonido continuo.","Ahora hacia arriba, de la cuerda fina a la gruesa.","Practica: abajo, abajo, abajo, abajo, a un tempo uniforme."],
2:"Rasgueos en negras: cuatro tiempos",
3:"Si el sonido «tropieza», probablemente estés apretando demasiado la púa. Una sujeción relajada da un sonido fluido.",
4:{q:"¿De dónde debe salir el movimiento del rasgueo?",o:["Del hombro","Del codo","De la muñeca","Solo de los dedos"],w:"El movimiento de muñeca es relajado, rápido y no provoca lesiones."},
5:"Rasguea cuerdas al aire durante 2 minutos seguidos con el metrónomo a 70. Vigila la uniformidad del sonido."}},

"guitar-3":{title:"El primer acorde: Em",goal:"Tocar un acorde limpio y rasguearlo a tiempo",b:{
0:"Em (mi menor) es el acorde más fácil del mundo: solo dos dedos, y se tocan las seis cuerdas.",
1:null,
2:["Dedo 2 en el traste 2 de la cuerda 5 (la).","Dedo 3 en el traste 2 de la cuerda 4 (re).","Pisa cerca del traste, ni encima ni en el medio.","Los dedos se apoyan en la punta, no tumbados.","Toca cuerda por cuerda y comprueba que cada una suena limpia."],
3:"¿Sonido «muerto» o que cerdea? Casi siempre la causa es un dedo tumbado que roza una cuerda vecina. Levanta la palma y curva más los dedos.",
4:"El método de comprobación de los profesores: toca cada cuerda por separado (un «arpegio»). La cuerda que no suena te dice exactamente qué dedo corregir.",
5:{q:"¿Qué hacer cuando una cuerda del acorde cerdea?",o:["Apretar más con todos los dedos","Comprobar qué dedo está tumbado rozando una cuerda vecina","Volver a afinar la guitarra","Cambiar las cuerdas"],w:"En el 90 % de los casos un dedo vecino toca la cuerda. La solución es curvar los dedos, no la fuerza."},
6:"Mantén Em y rasguea 16 tiempos seguidos. Suelta, sacude la mano y repite: cinco veces."}},

"guitar-4":{title:"Un segundo acorde y el primer cambio",goal:"Pasar de Em a Am sin parar",b:{
0:"Am (la menor) es exactamente la misma forma que Em, solo desplazada una cuerda y con un dedo más.",
1:null,
2:["Coge la forma de Em y desplázala una cuerda hacia las cuerdas finas.","Añade el dedo 1 en el traste 1 de la cuerda 2 (si).","No toques la cuerda 6.","Pasa Em → Am → Em → Am sin rasguear, solo con la mano."],
3:"<b>El secreto de los cambios:</b> practica el paso <u>sin rasguear</u>, 20 veces. El cerebro aprende el movimiento sin la presión del sonido. Después añade el rasgueo.",
4:"<b>Dedo ancla:</b> entre Em y Am dos dedos mantienen la misma forma. No levantes toda la mano: deslízala.",
5:{q:"¿Cuál es la forma más eficaz de practicar un cambio de acorde?",o:["Tocar la canción rápido una y otra vez","Practicar el movimiento de la mano solo, sin rasguear","Practicar cada acorde por separado","Practicar solo con metrónomo rápido"],w:"Separar el movimiento de la mano del rasgueo permite al cerebro aprender el gesto limpio y rápido."},
6:"60 cambios Em↔Am. Cuenta en voz alta. Cuatro minutos que lo cambian todo."}},

"guitar-5":{title:"El rasgueo de acompañamiento: abajo y arriba",goal:"Tocar el rasgueo más común del mundo",b:{
0:"El rasgueo más básico: <b>abajo, abajo-arriba, arriba-abajo-arriba</b>. Si en toda tu vida aprendes un solo rasgueo, que sea este.",
1:["Cuenta en voz alta: 1 y 2 y 3 y 4 y.","La mano se mueve arriba y abajo continuamente, como un péndulo, sin parar.","En los tiempos que no se tocan, la mano sigue moviéndose en el aire, simplemente no roza.","El patrón: ↓ . ↓↑ . ↑↓↑ (1, 2-y, 3-y-4-y)."],
2:"El rasgueo de acompañamiento básico",
3:"La mano que no se detiene es el secreto. Los principiantes paran la mano y pierden el ritmo. Deja que se mueva siempre.",
4:{q:"¿Por qué es importante que la mano derecha siga moviéndose aunque no rasguee?",o:["Para que se vea bien","Para mantener la sensación continua del ritmo","Para que la mano no se canse","No es importante"],w:"El movimiento continuo es tu reloj interno. Pararlo rompe el ritmo."},
5:"Toca Em con este rasgueo durante un minuto entero sin parar, y luego Am."}},

"guitar-6":{title:"El acorde de C y un cambio más exigente",goal:"Tocar un C limpio e integrarlo en una secuencia",b:{
0:"C (do mayor) exige tres dedos en tres trastes distintos. Es el acorde que separa a quien persevera de quien abandona.",
1:null,
2:["Dedo 1: traste 1, cuerda 2.","Dedo 2: traste 2, cuerda 4.","Dedo 3: traste 3, cuerda 5.","No toques la cuerda 6.","Asegúrate de que las cuerdas al aire 1 y 3 suenan libres."],
3:"Si la cuerda 1 (la fina) no suena, es que tu dedo 1 está tumbado encima. Gira ligeramente la muñeca hacia delante.",
4:{q:"¿Qué cuerdas no se tocan en un acorde de C abierto?",o:["La cuerda 1","La cuerda 6","Las cuerdas 5 y 6","Se tocan todas"],w:"En el acorde de C se empieza por la quinta cuerda. La sexta no forma parte del acorde."},
5:"Practica C → Am → C → Am, cuatro tiempos cada uno."}},

"guitar-7":{title:"G y D: tu primera canción de tres acordes",goal:"Tocar una canción completa con G, C y D",b:{
0:"Con G, C y D se pueden tocar miles de canciones. Es la «familia de sol»: los tres acordes centrales de la tonalidad de sol mayor.",
1:null,2:null,
3:"<b>La estructura clásica:</b> G – G – C – C – G – G – D – C – G. Cuatro tiempos por acorde.",
4:"Rasgueo de acompañamiento para la canción",
5:"Fíjate en que al pasar de G a C el dedo 3 puede quedarse en el mismo traste: es un «dedo ancla» que reduce el cambio a la mitad.",
6:{q:"¿Qué tienen en común los acordes G, C y D?",o:["Todos son menores","Son los tres acordes centrales de la escala de sol mayor","Están en el mismo traste","Usan los mismos dedos"],w:"Son los grados I, IV y V de la escala de sol mayor: el esqueleto armónico de la mayoría de las canciones."},
7:"Toca el ciclo G-C-G-D dos veces sin parar, aunque los cambios sean lentos."}},

"guitar-8":{title:"Cambios rápidos y dedos ancla",goal:"Acortar el tiempo de paso entre acordes",b:{
0:"Los cambios lentos son el problema número uno de los guitarristas principiantes. La solución no es fuerza ni velocidad, sino <b>eficiencia</b>.",
1:["<b>Dedo ancla:</b> identifica un dedo que se quede en su sitio entre dos acordes y no lo levantes.","<b>Movimiento mínimo:</b> levanta los dedos solo 2 mm de las cuerdas.","<b>Momento:</b> cambia de acorde en el último tiempo, no después.","<b>El ejercicio del reloj:</b> pon un minuto y cuenta cuántos cambios limpios logras. Supera tu récord cada día."],
2:"Anota tu récord de cambios en el diario de práctica de la aplicación. Un progreso medible es el motor más fuerte de la constancia.",
3:{q:"¿Qué es un «dedo ancla»?",o:["El pulgar detrás del mástil","Un dedo que se queda en su sitio al pasar entre dos acordes","El dedo más fuerte","Un dedo que pisa dos cuerdas"],w:"Un dedo ancla acorta el cambio y sirve de referencia a los demás dedos."},
4:"Un minuto de cambios C↔G. Anota el número. Vuelve mañana y supéralo."}},

"guitar-9":{title:"Rasgueos: variar el acompañamiento",goal:"Conocer tres rasgueos distintos",b:{
0:"Los mismos acordes con otro rasgueo suenan como una canción completamente distinta. Aquí van tres rasgueos que cubren casi cualquier estilo.",
1:"Rasgueo 1: balada lenta",
2:"Rasgueo 2: pop estándar",
3:"Rasgueo 3: acento a contratiempo",
4:"<b>El rasgueo a contratiempo</b> —tocar solo en los «y» entre tiempos— da una sensación saltarina y encaja con el reggae, el ska y muchos estilos folk.",
5:{q:"¿Qué cambia cuando se tocan los mismos acordes con otro rasgueo?",o:["La armonía","El carácter y el estilo de la canción","La altura de los sonidos","Solo la velocidad"],w:"El rasgueo es lo que define el estilo. Los mismos cuatro acordes pueden sonar a balada, a rock o a reggae."},
6:"Toca la misma secuencia de acordes con los tres rasgueos."}},

"guitar-10":{title:"Tu primer solo: la escala pentatónica",goal:"Improvisar un solo corto sobre cinco notas",b:{
0:"La escala pentatónica (cinco notas) es el secreto de todo solista de rock y blues. Su magia: es casi imposible tocar una nota «equivocada».",
1:"Pentatónica menor de la, ascendente",
2:["Coloca el dedo 1 en el traste 5, cuerda 6 (la).","El patrón: 5-8 en las cuerdas 6 y 5, 5-7 en las cuerdas 4 y 3, 5-8 en las cuerdas 2 y 1.","Toca el patrón subiendo y bajando hasta que los dedos lo recuerden.","Ahora olvida el orden: toca las notas al azar. Eso es improvisar."],
3:"Un buen solo no son muchas notas, sino notas con <b>silencios</b> entre ellas. Deja espacio para respirar.",
4:{q:"¿Por qué es fácil improvisar con la escala pentatónica?",o:["Solo tiene notas agudas","Contiene 5 notas que encajan todas armónicamente","Solo se puede tocar en una cuerda","Se toca despacio"],w:"De la escala se han quitado las notas «que chocan», así que cualquier combinación suena bien."},
5:"Improvisa 8 compases en la pentatónica sobre un metrónomo."}},

"guitar-11":{title:"Familias de acordes: A, E, Dm",goal:"Ampliar tu repertorio de acordes a ocho",b:{
0:null,1:null,2:null,
3:"Con los ocho acordes aprendidos (Em, Am, C, G, D, A, E, Dm) puedes tocar la gran mayoría de las canciones populares.",
4:"<b>La regla de compatibilidad:</b> los acordes de una misma «familia» (tonalidad) suenan bien juntos. Familia de do: C, Dm, Em, F, G, Am. Familia de sol: G, Am, Bm, C, D, Em.",
5:{q:"¿Qué acorde no pertenece a la familia de sol mayor?",o:["C","D","Em","F"],w:"F no forma parte de la escala de sol mayor (que lleva fa sostenido). Pertenece a la familia de do."},
6:"Elige cuatro acordes de una misma familia y tócalos en bucle."}},

"guitar-12":{title:"Pieza final y vistazo al futuro: la cejilla",goal:"Tocar una canción completa y conocer la siguiente etapa",b:{
0:"Has terminado el itinerario básico. Sabes afinar, rasguear, tocar ocho acordes, tres rasgueos y un solo.",
1:"Melodía de cierre: Amazing Grace (dominio público)",
2:"<b>La siguiente etapa: el acorde con cejilla.</b> El dedo 1 se tumba sobre todas las cuerdas e imita una cejilla mecánica. Eso abre todo el mástil.",
3:["Apoya el dedo 1 plano sobre las seis cuerdas en el traste 1.","Usa el lado externo del dedo, no la yema blanda.","Añade la forma de E con los dedos 2, 3 y 4 y tendrás un F.","No te desanimes: una cejilla limpia lleva a la mayoría entre 2 y 4 semanas."],
4:"Si sientes dolor en la muñeca al hacer cejilla, para. El problema es el ángulo del pulgar, no la falta de fuerza. Practica en el traste 5, donde las cuerdas son más blandas.",
5:{q:"¿Qué es un acorde con cejilla?",o:["Un acorde que solo usa cuerdas al aire","Un acorde en el que un dedo pisa varias cuerdas a la vez","Un acorde de cuatro notas","Un acorde rápido"],w:"El dedo 1 crea una «cejuela móvil» y permite desplazar las formas de acorde por todo el mástil."},
6:"Toca una canción completa de la biblioteca con acompañamiento y grábate."}},

/* ===================== UKELELE ===================== */
"ukulele-1":{title:"Ukelele en 10 minutos",goal:"Tocar un primer acorde y rasguearlo",b:{
0:"El ukelele es el instrumento más rápido del mundo para empezar: cuatro cuerdas de nailon blandas y una afinación estándar <b>G-C-E-A</b>.",
1:"Las cuerdas al aire",2:null,
3:["Sujeta el ukelele contra el cuerpo con el antebrazo derecho.","Coloca el dedo 3 en el traste 3 de la cuerda fina (la).","Rasguea suavemente hacia abajo con la yema del índice.","Ya está: has tocado un acorde de do."],
4:"En el ukelele se rasguea donde el mástil se une a la caja: ahí el sonido es más pleno.",
5:{q:"¿Cuál es la afinación estándar de un ukelele soprano?",o:["E-A-D-G","G-C-E-A","C-F-A-D","D-G-B-E"],w:"G-C-E-A es la afinación estándar, y el sol es en realidad más agudo que el do («afinación alta»)."},
6:"Rasguea el acorde de C durante un minuto a tempo uniforme."}},

"ukulele-2":{title:"Dos acordes = una canción entera",goal:"Pasar de C a Am",b:{
0:null,
1:"Am también necesita un solo dedo: el dedo 2 en el traste 2 de la cuerda gruesa (sol).",
2:"Rasgueo sencillo: cuatro golpes abajo",
3:"Toca cuatro tiempos de C, cuatro de Am y repite. Eso ya es una forma de canción legítima sobre la que se puede cantar.",
4:{q:"¿Cuántos dedos se necesitan para el acorde Am en el ukelele?",o:["Uno","Dos","Tres","Cuatro"],w:"Un solo dedo, en el traste 2 de la cuerda gruesa."},
5:"30 cambios C↔Am con metrónomo lento."}},

"ukulele-3":{title:"El tercer acorde: F",goal:"Tocar una secuencia de tres acordes",b:{
0:null,
1:"Con C, Am y F ya se pueden tocar cientos de canciones. La secuencia C – Am – F – C es un clásico.",
2:"Rasgueo pop",
3:{q:"¿Qué secuencia habitual usa estos tres acordes?",o:["F – F – F – F","C – Am – F – C","C – C# – D","Solo Am"],w:"C – Am – F es una de las secuencias más frecuentes de la música popular."},
4:"Toca la secuencia C-Am-F-C cuatro veces seguidas."}},

"ukulele-4":{title:"Rasgueos y cómo variarlos",goal:"Tres rasgueos de acompañamiento",b:{
0:"Rasgueo isleño",1:"Vals: tres tiempos",
2:"El rasgueo «isleño» (abajo, abajo-arriba, arriba-abajo-arriba) es el sonido clásico del ukelele.",
3:"Mantén la mano derecha completamente relajada. En el ukelele, fuerza equivale a sonido áspero.",
4:{q:"¿Cuántos tiempos tiene un compás de vals?",o:["2","3","4","6"],w:"El vals es 3/4: tres tiempos por compás, con el acento en el primero."},
5:"Toca la secuencia aprendida con dos rasgueos distintos."}},

"ukulele-5":{title:"G y Em: abrir el repertorio",goal:"Dominar cinco acordes",b:{
0:null,1:null,
2:"G requiere tres dedos en triángulo y Em es una diagonal descendente. Ambos necesitan práctica lenta al principio.",
3:"Practica el cambio C→G sin rasguear, 20 veces. Notarás que la mano «aprende» la forma en minutos.",
4:{q:"¿Qué ayuda más a dominar un cambio de acorde nuevo?",o:["Tocar rápido","Practicar el movimiento sin rasguear","Apretar más","Cambiar las cuerdas"],w:"Separar el movimiento del sonido acelera el aprendizaje motor."},
5:"30 cambios C↔G y 30 cambios Am↔Em."}},

"ukulele-6":{title:"Punteo",goal:"Tocar un arpegio básico",b:{
0:"En lugar de rasguear todas las cuerdas a la vez, las pulsaremos una tras otra: eso se llama <b>arpegio</b> y encaja con canciones tranquilas.",
1:["Pulgar: cuerda 4 (sol).","Índice: cuerda 3 (do).","Corazón: cuerda 2 (mi).","Anular: cuerda 1 (la).","Toca 4-3-2-1 y luego 1-2-3-4."],
2:"Arpegio sobre el acorde de C",
3:{q:"¿Qué es un arpegio?",o:["Un rasgueo fuerte","Tocar las notas de un acorde una tras otra","Un cambio de acorde rápido","Un tipo de púa"],w:"Arpegio = «acorde roto»: las notas se tocan en sucesión, no juntas."},
4:"Toca un arpegio sobre C, Am y F, cuatro tiempos cada uno."}},

"ukulele-7":{title:"Melodía en el ukelele",goal:"Tocar melodía, no solo acompañamiento",b:{
0:"El ukelele también toca melodías. Usaremos las cuerdas do, mi y la.",
1:"Campanita del lugar: melodía",
2:"Marca al principio las notas en el mástil con pequeñas pegatinas: es un atajo perfectamente legítimo.",
3:{q:"¿Cuál es la ventaja de tocar melodías en tu instrumento?",o:["Es más fácil que los acordes","Entrena el oído y el conocimiento de dónde está cada nota","Suena más fuerte","No tiene ventaja"],w:"Tocar melodía conecta el oído con el mástil: una destreza insustituible."},
4:"Toca la melodía dos veces despacio."}},

"ukulele-8":{title:"Cantar y tocar a la vez",goal:"Combinar acompañamiento y canto",b:{
0:"Es la destreza que te convierte en la persona a la que invitan a tocar en la hoguera. El secreto es la <b>automatización</b>: la mano debe tocar sin que pienses en ella.",
1:["Toca el acompañamiento hasta poder mantener una conversación mientras lo haces.","Di la letra en ritmo, sin cantar.","Tararea la melodía mientras tocas.","Solo ahora: canta letra y melodía a la vez."],
2:"Si el canto «arrastra» la mano, deja de cantar, estabiliza la mano y vuelve a intentarlo. La mano es el ancla.",
3:{q:"¿Cuál es la condición para cantar y tocar a la vez?",o:["Buena voz","Que el acompañamiento sea completamente automático","Acordes complicados","Un metrónomo"],w:"Un acompañamiento automático libera la atención para cantar."},
4:"Toca el acompañamiento y tararea una melodía durante un minuto entero."}},

"ukulele-9":{title:"Pieza final y vistazo al futuro",goal:"Tocar una canción completa de principio a fin",b:{
0:"Hava Naguila: melodía tradicional (dominio público)",
1:"Los siguientes pasos en el ukelele: acordes con cejilla, la técnica del «chunk» (apagado rítmico) y punteo avanzado.",
2:"Busca a alguien con quien tocar. Tocar en compañía mejora el sentido del ritmo mucho más que cualquier práctica en solitario.",
3:{q:"¿Qué paso se recomienda tras dominar los acordes abiertos?",o:["Cambiar de instrumento","Acordes con cejilla y rasgueos avanzados","Dejar de practicar","Aprender solo solfeo"],w:"La cejilla abre todo el mástil y permite tocar en cualquier tonalidad."},
4:"Grábate tocando una canción completa."}},

/* ===================== FLAUTA DULCE ===================== */
"recorder-1":{title:"Respiración y primera digitación",goal:"Producir un sonido limpio y tocar si",b:{
0:"La flauta dulce es el instrumento perfecto para empezar: barata, ligera y no exige fuerza ni manos grandes.",
1:["Sujeta la flauta a unos 45 grados del cuerpo.","Mano izquierda arriba, ¡siempre! Es el error más frecuente.","Apoya la punta de la boquilla en el labio inferior y cierra los labios con suavidad, sin morder.","Sopla suave susurrando «tu»: esa es la articulación con la que empieza cada nota."],
2:"Soplar demasiado fuerte dará un sonido chillón y agudo. La flauta necesita <b>muy poco</b> aire. Menos es más.",
3:"La nota si (B)",
4:"Primera nota: el pulgar izquierdo tapa el agujero trasero y el índice izquierdo el de arriba. Ya está: eso es si.",
5:{q:"¿Qué mano va siempre arriba en la flauta dulce?",o:["La derecha","La izquierda","Depende de si eres zurdo","Da igual"],w:"La mano izquierda va siempre arriba, en todos los instrumentos de viento madera."},
6:"Toca 10 si largos y estables, de 4 segundos cada uno."}},

"recorder-2":{title:"Tres notas: si, la, sol",goal:"Tocar una melodía corta",b:{
0:["<b>Si (B)</b>: pulgar + dedo 1 de la mano izquierda.","<b>La (A)</b>: se añade el dedo 2 izquierdo.","<b>Sol (G)</b>: se añade el dedo 3 izquierdo."],
1:"Ejercicio de tres notas",
2:"Asegúrate de que los dedos tapan los agujeros <b>por completo</b>, con la yema y no con la punta. Un agujero medio abierto produce un chillido.",
3:{q:"¿Qué ocurre cuando un agujero no se tapa del todo?",o:["El sonido es demasiado grave","El sonido chilla o silba","No pasa nada","La flauta se estropea"],w:"El aire que se escapa por un agujero medio abierto crea un silbido."},
4:"Toca el ejercicio 5 veces sin ningún gallo."}},

"recorder-3":{title:"La primera canción",goal:"Tocar una melodía conocida",b:{
0:"Mary Had a Little Lamb: melodía popular (dominio público)",
1:"Esta canción usa las notas que ya aprendiste más do y re: se añaden los dedos de la mano derecha.",
2:"Tararea primero la melodía y solo después tócala en el instrumento. Un oído que conoce la melodía guía los dedos.",
3:{q:"¿Qué paso se recomienda antes de tocar una canción nueva?",o:["Tocarla rápido","Tararearla y familiarizarse con la melodía","Leer las notas en voz alta","Afinar el instrumento"],w:"Un oído que conoce la melodía detecta el error al instante."},
4:"Toca la canción entera dos veces."}},

"recorder-4":{title:"Articulación con la lengua",goal:"Separar las notas con limpieza",b:{
0:"Sin lengua, todas las notas se funden en un solo sonido largo. La lengua es la puntuación de tu forma de tocar.",
1:["<b>«Tu»</b>: comienzo nítido de cada nota.","<b>«Du»</b>: comienzo suave, para pasajes cantables.","<b>Legato</b>: lengua solo en la primera nota del grupo.","<b>Staccato</b>: notas cortas y separadas."],
2:"Staccato frente a legato",
3:{q:"¿Para qué sirve la lengua al tocar la flauta dulce?",o:["Para mantener el sonido agudo","Para separar e iniciar las notas con limpieza","Para tocar más fuerte","Para afinar el instrumento"],w:"La lengua define el comienzo de cada nota; sin ella el sonido queda emborronado."},
4:"Toca una escala completa una vez en staccato y otra en legato."}},

"recorder-5":{title:"La escala completa de do mayor",goal:"Tocar una octava entera",b:{
0:"Escala de do mayor",
1:"Una escala completa exige cooperación entre las dos manos. La dificultad principal: el paso de las notas de la mano izquierda a las de la derecha.",
2:"Practica solo el paso problemático (sol→fa) veinte veces, en lugar de repetir toda la escala una y otra vez.",
3:{q:"¿Qué conviene hacer con un pasaje difícil?",o:["Repetir el pasaje entero sin parar","Aislar las dos notas problemáticas y trabajar solo esas","Saltarse el pasaje","Ralentizar toda la pieza"],w:"El trabajo focalizado es muchísimo más eficaz que repetir el conjunto."},
4:"Toca la escala de ida y vuelta 5 veces con el metrónomo a 60."}},

"recorder-6":{title:"La segunda octava",goal:"Producir notas agudas con el pulgar",b:{
0:"Para subir una octava, el pulgar «pellizca» el agujero trasero abriéndolo apenas. Es la técnica del <b>sobresoplado</b>.",
1:["Desliza el pulgar para que la uña abra una pequeña rendija.","Aumenta ligeramente la presión de aire.","Toca sol grave y sol agudo alternándolos."],
2:"Octavas",
3:"¿Sonido chillón? La rendija es demasiado grande. ¿Sonido grave? La rendija está cerrada. La diferencia es de un milímetro.",
4:{q:"¿Cuál es la función del pulgar izquierdo en las notas agudas?",o:["Tapar del todo","Abrir una pequeña rendija","Solo sujetar el instrumento","Abrir del todo"],w:"Una rendija pequeña cambia el modo de vibración y sube el sonido una octava."},
5:"Toca el ejercicio de octavas 10 veces."}},

"recorder-7":{title:"Sostenidos y bemoles",goal:"Tocar semitonos",b:{
0:"En la flauta dulce los semitonos se obtienen con <b>digitaciones de horquilla</b>: tapando agujeros no consecutivos.",
1:"El fa sostenido (F#) es la nota más importante que aprender: hace falta en cualquier pieza en sol mayor.",
2:"Escala de sol mayor (con F#)",
3:{q:"¿Qué es una digitación de horquilla?",o:["Tapar todos los agujeros","Tapar agujeros no consecutivos para crear un semitono","Abrir todos los agujeros","Una digitación a dos manos"],w:"Saltarse un agujero en medio de la digitación baja la nota un semitono."},
4:"Toca la escala de sol mayor de ida y vuelta."}},

"recorder-8":{title:"Expresión, respiración y fraseo",goal:"Tocar musicalmente, no mecánicamente",b:{
0:"Respirar no es solo una necesidad física: es puntuación. Se respira al final de una frase musical, no en mitad de una palabra.",
1:["Marca en la partitura dónde vas a respirar, antes de empezar a tocar.","Inspira por la boca, rápido y en silencio.","No respires en medio de una nota larga.","Termina la frase con una suavización delicada."],
2:"Toca una frase musical como si pronunciaras una oración: comienzo, clímax y final suavizado.",
3:{q:"¿Dónde es correcto respirar?",o:["Cada dos tiempos","Al final de una frase musical","Cada vez que se acaba el aire","En medio de una nota larga"],w:"Una respiración planificada al final de la frase conserva la línea musical."},
4:"Toca una pieza completa marcando de antemano tres puntos de respiración."}},

"recorder-9":{title:"Pieza final: Himno a la alegría",goal:"Tocar una obra clásica completa",b:{
0:"Himno a la alegría: Beethoven (dominio público)",
1:"La flauta dulce es una excelente puerta de entrada a otros instrumentos de viento: flauta travesera, clarinete, saxofón. La respiración y la articulación se transfieren casi tal cual.",
2:{q:"¿Qué instrumento se considera la continuación natural de la flauta dulce?",o:["La batería","La flauta travesera o el clarinete","El piano","El violín"],w:"La técnica de respiración y articulación pasa directamente a los vientos de madera."},
3:"Toca la pieza de principio a fin sin parar."}},

/* ===================== BATERÍA ===================== */
"drums-1":{title:"El ritmo: el lenguaje corporal de la música",goal:"Mantener un pulso estable",b:{
0:"No hace falta una batería para empezar. Una mesa, dos manos o dos lápices bastan perfectamente para las tres primeras lecciones.",
1:"Pulsos en negras: contar a cuatro",
2:["Pon el metrónomo a 72.","Palmea exactamente en cada pulso.","Cuenta en voz alta: 1-2-3-4.","Acentúa el primer pulso."],
3:"<b>La prueba:</b> si te adelantas o te retrasas, oyes cómo el metrónomo «se mueve». Si eres preciso, casi desaparece bajo tu palmada.",
4:{q:"¿Qué indica que eres preciso con el metrónomo?",o:["El metrónomo suena más fuerte","El metrónomo casi desaparece bajo tu sonido","Estás tocando rápido","No hay forma de saberlo"],w:"Cuando tu golpe cae exactamente sobre el clic, ambos sonidos se funden."},
5:"Dos minutos de palmadas precisas a 72."}},

"drums-2":{title:"El groove básico",goal:"Tocar el groove que está en el 80 % de las canciones",b:{
0:"El groove básico tiene tres componentes: <b>charles</b> (corcheas continuas), <b>bombo</b> (pulsos 1 y 3) y <b>caja</b> (pulsos 2 y 4).",
1:null,
2:["Empieza solo con el charles: 1-y-2-y-3-y-4-y.","Añade el bombo en los pulsos 1 y 3.","Añade la caja en los pulsos 2 y 4.","Toca los tres juntos, despacio."],
3:"Si una mano o un pie «tira abajo» a los demás, baja la velocidad un 20 %. La velocidad es un resultado, no un objetivo.",
4:{q:"¿En qué pulsos cae la caja en el groove básico?",o:["1 y 3","2 y 4","En todos","Solo en el 1"],w:"La caja en 2 y 4 es el «backbeat»: el pulso del rock y del pop."},
5:"Toca el groove durante 16 compases seguidos a 70."}},

"drums-3":{title:"Independencia de las extremidades",goal:"Separar manos y pies",b:{
0:"La independencia es la capacidad de que cada extremidad haga algo distinto a la vez. Se aprende: nadie nace con ella.",
1:["Toca solo charles y caja.","Solo charles y bombo.","Solo bombo y caja.","Combina los tres.","Mueve el bombo al «4-y» y siente cómo el cerebro se resiste. Eso es exactamente el entrenamiento."],
2:"Ejercicio de independencia",
3:"Trabaja la independencia 5 minutos al día: es mejor que una hora una vez por semana. Es aprendizaje motor y necesita repeticiones espaciadas.",
4:{q:"¿Cuál es la forma eficaz de desarrollar la independencia?",o:["Tocar rápido","Dividir en parejas de extremidades y combinar gradualmente","Tocar canciones enteras","Escuchar música"],w:"Dividir en parejas permite al cerebro construir el patrón paso a paso."},
5:"Trabaja tres parejas de extremidades, un minuto cada una."}},

"drums-4":{title:"Los redobles: la transición entre secciones",goal:"Tocar un redoble de un compás",b:{
0:"Un <b>redoble (fill)</b> es un pasaje corto que marca la transición entre secciones de la canción. El redoble básico: cuatro parejas de corcheas entre caja y toms.",
1:"Un redoble de un compás",
2:"La regla más importante del redoble: <b>volver a tiempo</b>. Un redoble impresionante que llega tarde es peor que uno sencillo que cae justo.",
3:{q:"¿Qué es lo más importante en un redoble?",o:["Que sea rápido","Que termine justo a tiempo para el pulso 1","Que sea largo","Que use todos los tambores"],w:"El redoble sirve a la canción: la precisión al volver importa más que el contenido."},
4:"Toca 4 compases de groove + un compás de redoble, cuatro veces."}},

"drums-5":{title:"Dinámica y peso",goal:"Controlar la fuerza de los golpes",b:{
0:"Un buen baterista no golpea fuerte: golpea <b>bien</b>. Un buen groove contiene al menos tres niveles de volumen.",
1:["Charles: suave y uniforme.","Bombo: medio, se siente en el estómago.","Caja: fuerte y nítida; es lo que se oye.","Prueba a tocar el mismo groove al 30 % de volumen y luego al 90 %."],
2:"El control del volumen viene del agarre: una sujeción relajada con un «punto de apoyo» entre pulgar y dedo da un golpe libre y con rebote.",
3:{q:"¿Qué elemento del groove debe sonar más fuerte?",o:["El charles","La caja","Todo al mismo volumen","El bombo"],w:"La caja es el «clic» del groove y por eso destaca."},
4:"Toca el groove a tres niveles de volumen distintos."}},

"drums-6":{title:"Grooves en distintos estilos",goal:"Conocer cuatro grooves",b:{
0:"Rock",1:"Shuffle / blues",2:"Vals",3:"Funk (semicorcheas)",
4:"El estilo no es solo un patrón: también es una sensación. El shuffle se balancea, el rock es recto, el funk es nítido y entrecortado.",
5:{q:"¿Qué distingue unos estilos rítmicos de otros?",o:["Solo la velocidad","El patrón de golpes y la sensación (recto o balanceado)","El tipo de tambores","El volumen"],w:"El patrón y el «groove feeling» son lo que define el estilo."},
6:"Toca cada uno de los cuatro grooves durante 8 compases."}},

"drums-7":{title:"Leer notación de batería",goal:"Descifrar un esquema de groove",b:{
0:"La notación de batería usa el mismo pentagrama, pero cada línea representa un tambor: charles arriba (X), caja en el centro, bombo abajo.",
1:["Línea superior con X: charles.","El tercer espacio: caja.","El espacio inferior: bombo.","Cuenta el compás: 1 y 2 y 3 y 4 y, y marca qué cae dónde."],
2:{q:"¿Qué significa una X en la notación de batería?",o:["Bombo","Un plato o el charles","Caja","Un silencio"],w:"Una cabeza de nota en forma de X indica un instrumento metálico: charles, crash o ride."},
3:"Escribe el groove básico en papel con notación."}},

"drums-8":{title:"Tocar con una canción",goal:"Sostener el ritmo junto a la música",b:{
0:"El baterista es el reloj del grupo. Para entrar: encuentra el pulso 1, cuenta un compás entero y entra.",
1:["Escucha la canción y encuentra el backbeat (2 y 4).","Palmea con él durante 30 segundos.","Toca el groove básico sobre la canción.","Añade un redoble cada 8 compases."],
2:"No rellenes cada segundo. Los silencios del baterista importan exactamente igual que los golpes.",
3:{q:"¿Cuál es el papel central del baterista en un grupo?",o:["Ser el más ruidoso","Mantener un ritmo estable y liderar las transiciones","Tocar solos","Cambiar los acordes"],w:"La estabilidad del ritmo es la base sobre la que se apoya todo el grupo."},
4:"Toca sobre una canción que te guste durante 3 minutos."}},

"drums-9":{title:"Cierre y vistazo al futuro",goal:"Combinar groove, redobles y dinámica",b:{
0:"Has terminado los fundamentos: groove, independencia, redobles, dinámica y estilos.",
1:["Toca 8 compases de groove rock.","Un redoble de un compás.","8 compases de shuffle.","Un redoble.","Termina con un crash en el pulso 1."],
2:"La siguiente etapa: los rudimentos (paradiddle, ruff, redoble doble): son las «escalas» del baterista.",
3:{q:"¿Qué son los rudimentos?",o:["Tipos de tambores","Patrones básicos de golpes con los que se construye todo","Ritmos latinos","Tipos de baquetas"],w:"Los rudimentos son los ladrillos de la técnica de batería."},
4:"Grábate tocando una secuencia completa."}},

/* ===================== BAJO ===================== */
"bass-1":{title:"Encuentro con el bajo",goal:"Tocar cuerdas al aire a tiempo",b:{
0:"El bajo eléctrico es el puente entre la batería y la guitarra. Cuatro cuerdas: <b>E-A-D-G</b>, una octava por debajo de las cuatro cuerdas gruesas de una guitarra.",
1:"Las cuerdas al aire",
2:["Mano derecha: índice y corazón se alternan, la «técnica de dos dedos».","El pulgar descansa sobre la pastilla.","Mano izquierda: un dedo por traste.","Toca cada cuerda al aire cuatro veces."],
3:"<b>La primera regla del bajista:</b> una nota limpia y corta en el sitio correcto vale más que diez impresionantes.",
4:{q:"¿Cuál es la afinación estándar de un bajo de cuatro cuerdas?",o:["G-C-E-A","E-A-D-G","E-A-D-G-B-E","D-A-D-G"],w:"E-A-D-G: las mismas que las cuatro cuerdas gruesas de una guitarra, una octava más grave."},
5:"Toca 8 pulsos en cada cuerda al aire con el metrónomo a 70."}},

"bass-2":{title:"Tu primera línea de bajo",goal:"Tocar la fundamental de cada acorde",b:{
0:"El trabajo básico del bajista: tocar la <b>fundamental</b> del acorde que toca la guitarra, en el primer pulso de cada compás.",
1:"Línea de bajo para la secuencia G-C-D",
2:["Acorde G → toca sol.","Acorde C → toca do.","Acorde D → toca re.","Un pulso largo por compás y luego cuatro negras."],
3:"Un buen bajista sabe dónde está cada nota sin pensar. Practica: «¿dónde está fa?» y encuéntralo en tres sitios distintos.",
4:{q:"¿Qué es la fundamental?",o:["La nota más aguda del acorde","La nota que da nombre al acorde","La primera nota de la escala","La cuerda gruesa"],w:"En un acorde de G la fundamental es sol. Esa es la nota básica del bajista."},
5:"Toca las fundamentales de la secuencia G-C-D-G, cuatro pulsos cada una."}},

"bass-3":{title:"Ritmo y groove con la batería",goal:"Encajar el bajo con el bombo",b:{
0:"La magia de un grupo ocurre cuando el bajo y el bombo tocan <b>exactamente juntos</b>. Eso se llama «lock».",
1:"Patrón de bombo para practicar",
2:["Escucha el patrón de bombo.","Toca una nota exactamente en cada golpe.","No añadas notas: solo sé preciso.","Ahora añade una nota de paso antes del compás siguiente."],
3:"Si tocas entre pulsos y no estás seguro, no toques. Un silencio preciso es mejor que una nota imprecisa.",
4:{q:"¿Con qué instrumento debe estar más sincronizado el bajo?",o:["La guitarra","El bombo","La voz","El piano"],w:"El dúo bajo + bombo es la base rítmica de cualquier formación."},
5:"Toca sobre el patrón de bombo durante dos minutos."}},

"bass-4":{title:"Las notas en el mástil",goal:"Encontrar cada nota en dos sitios",b:{
0:"En la cuerda mi: traste 1 = fa, traste 3 = sol, traste 5 = la. En la cuerda la: traste 2 = si, traste 3 = do.",
1:"<b>La regla de la octava:</b> la misma nota está también dos cuerdas más abajo y dos trastes más adelante. Es el atajo más útil del bajo.",
2:"La misma nota en dos octavas",
3:{q:"¿Dónde está la octava de una nota en el bajo?",o:["En la misma cuerda 12 trastes más arriba, o dos cuerdas abajo y dos trastes adelante","En el mismo traste de la cuerda contigua","No hay regla fija","Tres trastes atrás"],w:"Ambas son correctas, y el patrón de «dos y dos» es el más rápido de usar."},
4:"Elige una nota y encuéntrala en tres sitios distintos del mástil."}},

"bass-5":{title:"Walking bass",goal:"Conectar acordes con notas de paso",b:{
0:"<b>Walking bass</b>: una línea de bajo que toca cuatro notas por compás y conecta los acordes paso a paso.",
1:"Una walking line sencilla",
2:["Empieza en la fundamental.","Toca notas del acorde (fundamental, tercera, quinta).","Llega a una nota que esté a un paso de la fundamental siguiente.","Aterriza en la fundamental siguiente en el pulso 1."],
3:{q:"¿Para qué sirve una nota de paso en una walking bass?",o:["Para rellenar espacio","Para conducir con suavidad a la fundamental del acorde siguiente","Para sonar rápido","Para sustituir a la batería"],w:"Una nota de paso crea expectativa y una atracción natural hacia el acorde siguiente."},
4:"Toca una walking line sobre la secuencia C-F-G-C."}},

"bass-6":{title:"Técnicas de mano derecha",goal:"Conocer dedos, púa y slap",b:{
0:["<b>Con los dedos:</b> el sonido más cálido y habitual.","<b>Con púa:</b> sonido nítido y cortante, adecuado para rock y punk.","<b>Slap:</b> el pulgar golpea la cuerda gruesa y el dedo «tira» de la fina: el sonido funk característico."],
1:"Patrón de slap básico",
2:"En el slap el pulgar gira sobre un eje, no «pincha». El rebote forma parte del movimiento.",
3:{q:"¿Qué es la técnica de slap?",o:["Tocar con púa","Un golpe de pulgar y un tirón de dedo","Tocar con las dos manos","Apagar las cuerdas"],w:"La combinación de golpe de pulgar y tirón de dedo crea el sonido percusivo."},
4:"Toca ocho compases con cada una de las técnicas."}},

"bass-7":{title:"Apagado y control del ruido",goal:"Tocar limpio, sin cuerdas resonando",b:{
0:"El problema número uno en el bajo no son las notas equivocadas, sino el <b>ruido</b>: cuerdas que siguen vibrando.",
1:["El pulgar de la mano derecha se apoya en la cuerda gruesa y la apaga.","Los dedos de la mano izquierda que no tocan rozan ligeramente las cuerdas vecinas.","Después de cada nota, piensa en cómo la <b>detienes</b>, no solo en cómo la empiezas.","Toca una nota, apágala del todo y solo entonces toca la siguiente."],
2:{q:"¿Cuál es el problema más frecuente al tocar el bajo?",o:["Las notas equivocadas","El ruido de cuerdas sin apagar","El tempo lento","Las cuerdas finas"],w:"El control del ruido es la diferencia entre un aficionado y un profesional."},
3:"Toca nota-silencio-nota-silencio durante un minuto."}},

"bass-8":{title:"Una línea de bajo para una canción entera",goal:"Construir una línea de bajo propia",b:{
0:"Una buena línea de bajo se construye en tres fases: solo fundamentales → fundamentales en ritmo → añadir notas de paso y variación.",
1:"Riff de blues (ejercicio original)",
2:"Escucha a los bajistas de las canciones que te gustan. Fíjate en lo poco que tocan y en lo bien que encaja.",
3:{q:"¿Cuál es el orden correcto para construir una línea de bajo?",o:["Improvisar de inmediato","Fundamentales → ritmo → notas de paso","Copiar un solo","Empezar por la nota más aguda"],w:"La construcción gradual mantiene la línea estable y al servicio de la canción."},
4:"Construye una línea de bajo para una canción que conozcas, en las tres fases."}},

"bass-9":{title:"Cierre y vistazo al futuro",goal:"Tocar con un grupo",b:{
0:"Has terminado los fundamentos. Un bajista con tempo estable, sonido limpio y comprensión armónica es solicitado en cualquier banda.",
1:["Practica con metrónomo cada día, aunque sean 5 minutos.","Grábate: el oído capta lo que la mano no siente.","Toca con otras personas lo antes posible.","Aprende la escala mayor y la menor natural por todo el mástil."],
2:{q:"¿Cuál es la cualidad más importante en un bajista?",o:["La velocidad","Tempo estable y sonido limpio","Conocer el solfeo","Equipo caro"],w:"La estabilidad es lo que hace que todo el grupo suene bien."},
3:"Toca una canción completa de principio a fin con metrónomo."}}

});

/* ---- los cuatro instrumentos nuevos ---- */
I18N.registerLessons("es", {

"violin-1":{title:"Cómo sostenerlo y las cuerdas al aire",goal:"Producir un sonido limpio en las cuatro cuerdas",b:{
0:"El violín es el instrumento donde <b>el oído guía al dedo</b>. No hay trastes, así que cada nota se construye escuchando, y eso es precisamente lo que lo convierte en el mejor maestro para el oído.",
1:"Cuatro cuerdas, de la más gruesa a la más fina: <b>sol, re, la, mi</b>. Entre cada par hay una quinta.",
3:["Apoya el violín sobre la clavícula, con la mandíbula en la barbada.","La mano izquierda sostiene el mástil con ligereza: no lo aprieta.","El arco se apoya en la cuerda a medio camino entre el puente y el diapasón.","Tira del arco despacio y con presión pareja. Un sonido limpio vale más que uno fuerte."],
4:"¿Un silbido? Una de tres cosas: presión despareja, el arco demasiado lejos del puente, o velocidad cambiante. Ve más despacio.",
5:{q:"¿Cómo se afinan las cuerdas del violín?",o:["Por cuartas","Por quintas","Por octavas","Por terceras"],w:"Sol-re-la-mi: una quinta entre cada par de cuerdas vecinas."},
6:"Toca cada cuerda al aire ocho veces con arco entero, sin silbidos."}},

"violin-2":{title:"El primer dedo",goal:"Tocar cuatro notas nuevas",b:{
0:"El primer dedo se coloca a <b>un tono entero</b> de la cuerda al aire. Es el punto de anclaje de toda la mano.",
2:"Pega un trocito de cinta donde cae el primer dedo. No es hacer trampa: así aprenden todos los violinistas del mundo en su primer año.",
3:"Cuerda al aire y primer dedo",
4:{q:"¿Cuál es la distancia entre la cuerda al aire y el primer dedo?",o:["Un semitono","Un tono entero","Un tono y medio","Dos tonos"],w:"Un tono entero, y es la primera distancia que aprende el oído."},
5:"Toca el ejercicio despacio y comprueba cada nota con el afinador de la aplicación."}},

"violin-3":{title:"Una primera melodía",goal:"Tocar una pieza entera en dos cuerdas",b:{
0:"Con las cuerdas al aire y el primer dedo ya puedes tocar una melodía de verdad.",
2:"Ejercicio en dos cuerdas",
3:"<b>La regla del primer año:</b> lento y limpio siempre gana a rápido y sucio.",
4:{q:"¿Qué importa más en esta etapa?",o:["Tocar rápido para avanzar","Tocar despacio y escuchar cada nota","Saltarse las notas difíciles","Tocar lo más fuerte posible"],w:"En el violín cualquier imprecisión se oye de inmediato. Ir despacio es el atajo."},
5:"Toca la melodía cinco veces, un poco más rápido cada vez."}},

"violin-4":{title:"Tres dedos: tu primera escala",goal:"Tocar la escala de re mayor en dos cuerdas",b:{
0:"En el violín la escala no se construye con trastes sino con un <b>patrón fijo de dedos</b>. En cuanto la mano lo aprende, se repite en cualquier cuerda.",
1:"En la cuerda de re: dedo 1 = mi, dedo 2 = fa sostenido, dedo 3 = sol. Fíjate en que los dedos 2 y 3 <b>se tocan</b>: esa es la señal de que el patrón es correcto.",
3:"Escala de re mayor",
4:"Los dedos 2 y 3 van juntos en una escala mayor. Si se abre un hueco entre ellos, el fa sostenido saldrá bajo.",
5:{q:"¿Qué caracteriza la posición de los dedos 2 y 3 en mayor?",o:["Un hueco amplio entre ellos","Se tocan entre sí","El dedo 3 no se usa","No hay una regla fija"],w:"Su cercanía es el semitono entre el tercer y el cuarto grado."},
6:"Toca la escala en ambos sentidos diez veces, despacio, comprobando cada nota con el afinador."}},

"violin-5":{title:"La distribución del arco",goal:"Controlar la duración y la fuerza del sonido",b:{
0:"El arco es la <b>respiración</b> del violín. Una nota larga pide arco lento; una corta, poco arco, y la presión se mantiene constante.",
1:["Marca tres zonas: talón, medio y punta.","Toca una redonda con arco entero, del talón a la punta, en cuatro segundos.","Toca cuatro negras en ese mismo arco: cada una un cuarto del recorrido.","Ahora toca corcheas usando solo el medio del arco."],
2:"Distribución del arco",
3:"¿El sonido se debilita al final del arco? La presión baja junto con el brazo. Mantenla pareja hasta la punta.",
4:{q:"¿Qué determina la duración de una nota en el violín?",o:["La presión del dedo","La velocidad del arco","Cómo se sostiene el instrumento","El grosor de la cuerda"],w:"La velocidad del arco fija la duración; la presión, el volumen."},
5:"Toca una escala entera con arco completo por nota, y luego con medio arco."}},

"violin-6":{title:"Segunda cuerda y cambios",goal:"Pasar entre cuerdas sin ruido",b:{
0:"El paso entre cuerdas es donde se oye la diferencia entre un principiante y un músico. El secreto: <b>el brazo empieza a moverse antes de que cambie la nota</b>.",
2:"Ejercicio de cambios",
3:"Si se oye un sonido doble durante el cambio, el arco tocó dos cuerdas. Lo que debe cambiar es el ángulo, no la presión.",
4:{q:"¿Qué provoca un sonido doble al cambiar de cuerda?",o:["Demasiada presión","El arco toca dos cuerdas","El instrumento está desafinado","El dedo está mal colocado"],w:"Es el ángulo del arco lo que separa las cuerdas."},
5:"Toca el ejercicio diez veces, completamente limpio."}},

"violin-7":{title:"Un primer vibrato",goal:"Conocer el movimiento del vibrato",b:{
0:"El vibrato es un <b>pequeño balanceo del dedo</b> que da calidez al sonido. Se enseña más tarde de lo que se cree, y es a propósito: disimula la imprecisión, así que primero se aprende a tocar limpio sin él.",
1:["Coloca el dedo 2 en la cuerda de la, sin arco.","Balancea la mano adelante y atrás desde la muñeca, no desde el dedo.","El dedo se queda en su sitio: solo varía ligeramente la altura.","Añade el arco solo cuando el movimiento sea fluido."],
2:"Un vibrato rápido y estrecho suena a temblor. Uno lento y amplio suena a canto. Empieza despacio.",
3:{q:"¿De dónde viene el movimiento del vibrato?",o:["Del dedo","De la muñeca","Solo del codo","Del hombro"],w:"El movimiento nace en la muñeca; el dedo solo lo acompaña."},
4:"Practica el movimiento un minuto sin arco y otro minuto con arco."}},

"violin-8":{title:"Una melodía completa",goal:"Tocar una pieza conocida de principio a fin",b:{
0:"Ahora todo se junta: el patrón de dedos, la distribución del arco y los cambios de cuerda.",
1:"Melodía para dos cuerdas",
2:"Toca primero sin arco, en pizzicato, para comprobar que los dedos están en su sitio. Después añade el arco.",
3:{q:"¿Qué conviene comprobar antes de añadir el arco?",o:["El volumen","Que los dedos estén bien colocados","El tempo","La posición de la cabeza"],w:"El pizzicato aísla la mano izquierda y revela las imprecisiones al instante."},
4:"Toca la melodía cinco veces: dos en pizzicato y tres con arco."}},

"violin-9":{title:"Resumen y qué viene después",goal:"Tocar con confianza y saber hacia dónde ir",b:{
0:"Has terminado los fundamentos: la sujeción, las cuerdas al aire, el patrón de dedos, la distribución del arco y los cambios. Todo lo demás se construye sobre esto.",
1:"Qué viene después: <b>la segunda posición</b> (mover toda la mano por el mástil), <b>tocar en dos cuerdas a la vez</b> y <b>leer partitura</b> mientras tocas.",
2:"Pieza final",
3:"<b>El error clásico del segundo año:</b> acelerar antes de que el sonido esté limpio. Toca todo con metrónomo lento y adelantarás a quien se apresuró.",
4:{q:"¿Cuál es el siguiente paso natural en el violín?",o:["Tocar más rápido","La segunda posición y la lectura","Cambiar de instrumento","Prescindir del arco"],w:"La segunda posición abre el resto del mástil, y la lectura abre el repertorio."},
5:"Toca la pieza final y grábate. Volver a escucharse es el maestro más honesto."}},

"harmonica-1":{title:"Soplar y aspirar",goal:"Producir un sonido limpio desde un solo agujero",b:{
0:"La armónica es el único instrumento donde <b>tanto soplar como aspirar producen sonido</b>, y dos sonidos distintos desde el mismo agujero.",
1:"Una armónica en do tiene diez agujeros y veinte lengüetas. El cuarto agujero es el punto de partida de casi cualquier melodía.",
3:["Sujeta la armónica entre el pulgar y el índice, con los números hacia arriba.","Redondea los labios como si dijeras «u».","Sopla suavemente en el agujero cuatro: sale do.","Ahora aspira desde el mismo agujero: sale re."],
4:"¿Salen varias notas a la vez? Tienes la boca demasiado abierta. Estrecha los labios hasta que quede una sola nota limpia.",
5:{q:"¿Qué distingue a la armónica de otros instrumentos de viento?",o:["No tiene notas agudas","Soplar y aspirar producen sonido","Hay que afinarla cada vez","Hay que pulsar botones"],w:"Cada agujero tiene dos lengüetas: una para soplar y otra para aspirar."},
6:"Alterna soplar y aspirar en el agujero 4, veinte veces, con sonido limpio."}},

"harmonica-2":{title:"Cuatro agujeros: tu primera melodía",goal:"Tocar una melodía conocida",b:{
0:"Los agujeros del 4 al 7 contienen una escala completa de do mayor. Ahí vive casi cualquier canción popular.",
2:"Mira la flecha sobre el diagrama: hacia arriba, soplas; hacia abajo, aspiras. Eso es todo lo que hay que recordar.",
3:"La escala en la armónica",
4:{q:"¿En qué agujeros está la escala completa de do mayor?",o:["Del 1 al 4","Del 4 al 7","Del 7 al 10","En todos"],w:"Solo del 4 al 7 la escala está completa sin bending."},
5:"Toca la escala en ambos sentidos diez veces."}},

"harmonica-3":{title:"Tu primera canción",goal:"Tocar una melodía entera de memoria",b:{
0:"Ahora se junta todo. Esta melodía usa solo los agujeros del 4 al 6.",
2:"Melodía para cuatro agujeros",
3:"Intenta tocar sin mirar los números. En la armónica, el oído encuentra el agujero antes que el ojo.",
4:{q:"¿Cuál es la mejor forma de aprender una melodía en la armónica?",o:["Memorizar los números de los agujeros","Escuchar y buscar de oído","Contar las respiraciones","Leer partitura"],w:"La armónica se creó para tocar de oído: esa es su fuerza."},
5:"Toca la melodía tres veces con los ojos cerrados."}},

"harmonica-4":{title:"Tocar un solo agujero",goal:"Producir una nota limpia sin vecinas",b:{
0:"Hasta ahora quizá sonaban varias notas juntas. Ahora aprendes a sacar <b>solo una</b>, y eso es lo que convierte el ruido en melodía.",
1:["Mete la armónica más adentro de los labios, como si bebieras.","La lengua reposa abajo y relajada.","Estrecha la abertura de los labios hasta que suene una sola nota.","Compruébalo: sopla en el agujero 4; si oyes un acorde, tus labios están demasiado abiertos."],
3:"Un segundo método, el <b>bloqueo con la lengua</b>: cubre tres agujeros con la boca y bloquea dos con la lengua. Queda uno abierto.",
4:{q:"¿Por qué suenan varias notas a la vez?",o:["La armónica está rota","La abertura de los labios es demasiado ancha","Soplas demasiado fuerte","Los agujeros están obstruidos"],w:"Una boca ancha cubre varios agujeros a la vez."},
5:"Toca los agujeros 4, 5 y 6 soplando: cada uno por separado y limpio, veinte veces."}},

"harmonica-5":{title:"La segunda octava",goal:"Ampliar el registro a los agujeros del 1 al 7",b:{
0:"Los agujeros graves (1–3) dan los sonidos profundos, y los agudos (7–10) los penetrantes. La mayoría de las melodías vive en el medio.",
2:"Fíjate en algo curioso: a partir del agujero 7 <b>la aspiración es más grave que el soplo</b>, al revés que en los agujeros graves. Es una propiedad de la afinación, no una avería.",
3:"Registro completo",
4:{q:"¿Qué cambia a partir del agujero 7?",o:["Nada","La aspiración pasa a ser más grave que el soplo","No se puede aspirar","El sonido es más débil"],w:"Es una inversión incorporada en la afinación Richter."},
5:"Toca todos los soplos del agujero 1 al 10 y de vuelta."}},

"harmonica-6":{title:"Ritmo y respiración",goal:"Tocar a tiempo sin quedarte sin aire",b:{
0:"En la armónica la respiración es a la vez el sonido y el combustible. Toca demasiado en una sola dirección y te quedarás sin aire.",
1:"Alternancia de soplo y aspiración",
2:"<b>La regla:</b> si la melodía pide tres soplos seguidos, busca un sitio para cambiar de dirección. Casi siempre la misma nota está en otro agujero.",
3:"Ejercicio de respiración",
4:{q:"¿Qué haces cuando te quedas sin aire a mitad de frase?",o:["Soplar más fuerte","Buscar un sitio para cambiar de dirección","Dejar de tocar","Tocar más rápido"],w:"Cambiar de dirección es la forma de respirar de la armónica."},
5:"Toca el ejercicio dos minutos seguidos sin quedarte sin aliento."}},

"harmonica-7":{title:"Acordes y trémolo",goal:"Usar varios agujeros juntos a propósito",b:{
0:"Hasta ahora luchábamos contra las notas vecinas. Ahora las <b>usamos a propósito</b>: varios agujeros juntos dan un acorde completo.",
1:"Soplar en los agujeros 1–4 da un acorde de do mayor. Aspirar en los agujeros 1–4 da un acorde de sol.",
2:"<b>Trémolo:</b> agita la mano que sostiene la armónica delante de la boca. El sonido ondula y recuerda a un tren.",
3:"Acompañamiento de acordes",
4:{q:"¿Qué acorde sale al soplar en los agujeros 1 a 4?",o:["Sol mayor","Do mayor","La menor","Re mayor"],w:"Los soplos están construidos con las notas del acorde de do: do, mi y sol."},
5:"Toca un acompañamiento de acordes sobre una canción que conozcas, dos minutos."}},

"harmonica-8":{title:"Una canción entera",goal:"Tocar una melodía conocida de principio a fin",b:{
0:"Ahora se junta todo: agujero único, ritmo y respiración planificada.",
2:"Melodía completa",
3:"Marca de antemano dónde soplas y dónde aspiras. Planificar evita quedarse sin aliento.",
4:{q:"¿Qué ayuda a no quedarse sin aliento?",o:["Tocar flojo","Planificar de antemano los soplos y las aspiraciones","Tocar rápido","Acortar la canción"],w:"Planificar la dirección del aire es la destreza central de la armónica."},
5:"Toca la melodía cinco veces seguidas sin parar."}},

"harmonica-9":{title:"Resumen y qué viene después",goal:"Saber qué has aprendido y hacia dónde ir",b:{
0:"Has terminado los fundamentos: soplo y aspiración, agujero único, registro completo, ritmo, acordes y una canción entera.",
1:"Qué viene después: el <b>bending</b>, cambiar la altura del sonido con la lengua, que permite tocar las notas que no están en la afinación. Eso es lo que da a la armónica su color de blues.",
2:"Pieza final",
3:"El bending lleva meses, no días. No lo practiques antes de que tus notas simples estén perfectamente limpias.",
4:{q:"¿Qué hace posible el bending?",o:["Otra armónica","Cambiar la forma de la boca y la lengua","Soplar fuerte","Cambiar las lengüetas"],w:"La forma de la cavidad bucal modifica la altura del sonido."},
5:"Toca la pieza final y grábate."}},

"glock-1":{title:"El primer golpe",goal:"Producir un sonido limpio y entender la disposición",b:{
0:"El glockenspiel es el instrumento melódico más fácil para empezar: <b>nada que afinar, sin digitación y sin aire</b>. Golpeas y sale la nota correcta.",
1:"Las láminas están dispuestas exactamente como las teclas de un piano: una fila larga de blancas y, encima, grupos de dos y de tres.",
2:"Golpea la lámina marcada: esto es do",
3:["Sujeta la baqueta con soltura, entre el pulgar y el índice.","Golpea el centro de la lámina, no el extremo.","Levanta la baqueta justo después del golpe. Una baqueta apoyada ahoga el sonido.","Basta con un golpe suave. El instrumento hace el trabajo."],
4:"¿Sonido apagado? La baqueta se queda sobre la lámina. Piensa en rebotar, no en presionar.",
5:{q:"¿Dónde se golpea la lámina?",o:["En el extremo","En el centro","Cerca del tornillo","Da igual"],w:"El centro da el sonido más pleno. Los extremos suenan apagados."},
6:"Golpea cada lámina blanca una vez, de grave a agudo, con sonido limpio."}},

"glock-2":{title:"La escala y tu primera melodía",goal:"Tocar una melodía conocida",b:{
0:"La escala de do mayor es simplemente todas las láminas blancas seguidas. Con eso basta para la primera melodía.",
1:"Escala de do mayor",
2:"Primera melodía",
3:"<b>Alternar las manos:</b> derecha-izquierda-derecha-izquierda. Duplica la velocidad sin esfuerzo añadido.",
4:{q:"¿Cuál es la ventaja de alternar las manos?",o:["Un sonido más fuerte","Se toca más rápido sin esfuerzo","Las láminas se desgastan menos","No hay ventaja"],w:"Una sola mano tiene que volver; dos manos se alternan sin interrupción."},
5:"Toca la melodía alternando las manos, cinco veces."}},

"glock-3":{title:"Ritmo y dinámica",goal:"Tocar con distintas intensidades y a tiempo",b:{
0:"En el glockenspiel el sonido es corto, así que <b>el tiempo y la intensidad</b> son toda la expresión disponible. Eso es lo que convierte una interpretación corriente en una memorable.",
1:"Ritmo básico",
2:"Prueba a tocar la misma melodía una vez fuerte y otra suave. La diferencia es mayor de lo que parece.",
3:"La misma melodía, otro ritmo",
4:{q:"¿Qué genera expresión en el glockenspiel?",o:["La duración de las notas","La intensidad y el tiempo","La afinación de las láminas","El número de baquetas"],w:"El sonido es corto y fijo: tus herramientas son el volumen y la precisión temporal."},
5:"Toca la melodía tres veces: suave, media y fuerte."}},

"glock-4":{title:"Dos manos y saltos",goal:"Tocar un pasaje que se mueve entre zonas",b:{
0:"En el glockenspiel la mano no se queda quieta. <b>El ojo guía y la mano sigue</b>, y eso se aprende por separado.",
1:"Tres puntos de referencia: do, sol y do agudo",
2:["Localiza los tres puntos de anclaje en el instrumento.","Golpea do y luego sol, sin mirar la baqueta.","Añade el do agudo.","Ahora toca los tres seguidos con metrónomo a 60."],
3:"Mira la lámina <b>siguiente</b> mientras golpeas la actual. Ese es el secreto de cualquier percusionista de láminas.",
4:{q:"¿Adónde se mira mientras se toca?",o:["A la baqueta","A la lámina siguiente","Solo a la partitura","Da igual"],w:"La mirada va por delante de la mano, igual que al leer."},
5:"Toca do-sol-do veinte veces sin fallar."}},

"glock-5":{title:"Las láminas superiores",goal:"Tocar en una escala con sostenido",b:{
0:"Las láminas superiores son los semitonos, exactamente como las teclas negras del piano y en los mismos grupos de dos y de tres.",
1:"Escala de sol mayor: atención al fa sostenido",
2:"Las láminas superiores son más estrechas. Apunta al centro o la baqueta resbalará.",
3:{q:"¿Cómo se disponen las láminas superiores?",o:["En una fila uniforme","En grupos de dos y de tres","Al azar","No hay láminas superiores"],w:"Exactamente como las teclas negras de un piano."},
4:"Toca la escala de sol mayor en ambos sentidos, cinco veces."}},

"glock-6":{title:"Ritmo más complejo",goal:"Tocar corcheas y notas con puntillo",b:{
0:"El sonido del glockenspiel es corto, así que <b>la precisión rítmica</b> se oye enseguida. Aquí se aprende a dividir el pulso.",
1:"Corcheas",
2:"Melodía en corcheas",
3:"Cuenta en voz alta: «uno-y-dos-y». Contar en voz alta es más preciso que contar mentalmente.",
4:{q:"¿Qué ayuda a la precisión rítmica?",o:["Tocar fuerte","Contar en voz alta","Tocar rápido","Mirarse las manos"],w:"Contar en voz alta conecta el cuerpo con el tiempo."},
5:"Toca la melodía con metrónomo a 70 y luego a 85."}},

"glock-7":{title:"Dos voces",goal:"Tocar melodía y acompañamiento a la vez",b:{
0:"Dos manos son dos voces. Una mano toca la melodía y la otra añade una nota de apoyo.",
1:"Acorde de do: las tres notas juntas",
2:"Melodía con apoyo",
3:"Empieza con la segunda mano golpeando solo en el primer tiempo de cada compás. Con eso ya suena lleno.",
4:{q:"¿Cuál es la forma más sencilla de añadir una segunda voz?",o:["Tocarlo todo dos veces","Una nota de apoyo en el primer tiempo","Tocar más rápido","Añadir una tercera baqueta"],w:"Un solo apoyo por compás ya crea sensación de acompañamiento."},
5:"Toca la melodía con apoyo, cinco veces."}},

"glock-8":{title:"Una pieza para interpretar",goal:"Tocar una pieza completa con seguridad",b:{
0:"Ahora se combina todo: saltos, láminas superiores, ritmo y dos voces.",
1:"Pieza para interpretar",
2:"Trabaja la pieza en tres secciones separadas y únelas solo después. Así estudian los profesionales.",
3:{q:"¿Cómo se aprende una pieza larga?",o:["Tocándola una y otra vez","Dividiéndola en secciones y luego uniéndolas","Tocando solo el principio","Acelerando poco a poco"],w:"Dividir ahorra tiempo e impide que los errores se fijen."},
4:"Toca la pieza tres veces seguidas sin parar."}},

"glock-9":{title:"Resumen y qué viene después",goal:"Saber qué has aprendido y hacia dónde ir",b:{
0:"Has terminado: el golpe limpio, la escala, los saltos, las láminas superiores, el ritmo y las dos voces.",
1:"Qué viene después: el <b>xilófono y la marimba</b> (láminas de madera, sonido más cálido), <b>cuatro baquetas</b> en dos manos y <b>leer partitura</b> mientras tocas.",
2:"Pieza final",
3:"El glockenspiel es una puerta excelente a toda la percusión melódica. La destreza se transfiere casi por completo.",
4:{q:"¿Cuál es la diferencia entre glockenspiel y xilófono?",o:["El tamaño","Láminas de metal frente a láminas de madera","El número de láminas","La afinación"],w:"El metal da un sonido brillante y largo; la madera, cálido y corto."},
5:"Toca la pieza final y grábate."}},

"mandolin-1":{title:"Primer contacto y cuerdas al aire",goal:"Producir un sonido limpio y conocer la afinación",b:{
0:"La mandolina se afina <b>exactamente igual que un violín</b> —sol, re, la, mi— pero tiene trastes. Cada nota está en un sitio fijo y no hay que buscar nada de oído.",
2:["Sujeta la púa entre el pulgar y el índice, solo por la punta.","Toca hacia abajo y hacia arriba alternando: ese es el movimiento básico.","Mano izquierda: presiona justo detrás del traste, no encima.","Toca cada par de cuerdas al aire cuatro veces."],
3:"Cada nota tiene dos cuerdas contiguas. Eso es lo que da a la mandolina su sonido tintineante.",
4:{q:"¿En qué se diferencia la mandolina del violín?",o:["En la afinación","En que tiene trastes","En el número de cuerdas","Solo en el tamaño"],w:"La afinación es idéntica; la diferencia son los trastes, y son los que facilitan el comienzo."},
5:"Toca cada cuerda al aire ocho veces, abajo y arriba."}},

"mandolin-2":{title:"Primeras notas en el mástil",goal:"Tocar tu primera escala",b:{
0:"Gracias a los trastes, encontrar una nota en la mandolina es cuestión de contar, no de escuchar.",
2:"Cinco notas",
3:"Un dedo por traste: esa es la regla que te ahorra años de correcciones.",
4:{q:"¿Cómo se encuentra una nota en la mandolina?",o:["Solo de oído","Por el número de traste","Por el color de la cuerda","No se puede saber con certeza"],w:"Los trastes fijan la altura con precisión."},
5:"Toca las cinco notas en ambos sentidos, diez veces."}},

"mandolin-3":{title:"Una primera melodía",goal:"Tocar una pieza entera",b:{
0:"Ahora se junta todo: cuerdas al aire, notas en el mástil y una púa regular.",
2:"Melodía para mandolina",
3:"<b>Trémolo:</b> repetición rápida de la púa sobre la misma nota. Es el sonido que todos reconocen como mandolina, pero solo cuando la púa normal ya es estable.",
4:{q:"¿Qué es el trémolo?",o:["Un cambio rápido de acordes","Repetición rápida de la púa sobre la misma nota","Tocar en dos cuerdas","Frenar al final"],w:"Es la técnica distintiva de la mandolina."},
5:"Toca la melodía cinco veces con púa pareja."}},

"mandolin-4":{title:"Tu primer acorde",goal:"Tocar un acorde de sol y enlazar con él",b:{
0:"En la mandolina un acorde son <b>solo dos dedos</b> en la mayoría de los casos, muchos menos de los que exige una guitarra.",
2:["Dedo 1 en la cuerda de la, traste 2.","Dedo 2 en la cuerda de mi, traste 3.","Las otras dos cuerdas quedan al aire.","Toca hacia abajo sobre los cuatro pares."],
3:"Presiona justo detrás del traste, no encima. Ahí hace falta menos fuerza.",
4:{q:"¿Cuántos dedos hacen falta para un acorde básico de mandolina?",o:["Cuatro","Dos","Tres","Ninguno"],w:"Con dos basta para la mayoría de los acordes al aire."},
5:"Alterna entre el acorde de sol y las cuerdas al aire, veinte veces."}},

"mandolin-5":{title:"Dos acordes y una canción",goal:"Acompañar una canción entera con dos acordes",b:{
0:"Con dos acordes ya se pueden acompañar cientos de canciones. El cambio entre ellos es todo el trabajo.",
1:"Púa abajo-arriba",
2:"<b>La regla del cambio:</b> levanta los dedos un instante antes del tiempo, no sobre él. Así no queda un hueco en el ritmo.",
3:"Ejercicio de acompañamiento",
4:{q:"¿Cuándo se levantan los dedos al cambiar de acorde?",o:["Justo sobre el tiempo","Un instante antes del tiempo","Después del tiempo","Da igual"],w:"Levantarlos antes mantiene la continuidad del ritmo."},
5:"Alterna los dos acordes durante dos minutos sin parar."}},

"mandolin-6":{title:"El trémolo",goal:"Producir un sonido sostenido con púa repetida",b:{
0:"La mandolina no tiene sonido largo: se apaga enseguida. El <b>trémolo</b> es la solución: una repetición rápida que crea la ilusión de un sonido sostenido.",
1:["Sujeta la púa muy suelta: esa es la clave.","Muévete desde la muñeca, no desde el codo.","Empieza lento y parejo, y acelera solo después.","Toca una nota en trémolo durante cuatro segundos."],
2:"Una empuñadura tensa da un trémolo entrecortado. Cuanto más blanda, más liso es el sonido.",
3:"Nota larga en trémolo",
4:{q:"¿Qué es lo más importante en el trémolo?",o:["La velocidad","Una empuñadura relajada","Mucha presión","Una púa gruesa"],w:"La relajación permite la velocidad; la tensión la impide."},
5:"Practica el trémolo sobre una sola nota, un minuto por cuerda."}},

"mandolin-7":{title:"Escalas en dos octavas",goal:"Ampliar el registro a lo largo del mástil",b:{
0:"Gracias a la afinación por quintas, el mismo patrón de dedos se repite en cada par de cuerdas. Se aprende una vez y se toca en todas partes.",
2:"Escala de sol en dos octavas",
3:"El patrón aprendido en la cuerda de sol funciona exactamente igual en la de re. Ese es el gran ahorro de la afinación por quintas.",
4:{q:"¿Cuál es la ventaja de afinar por quintas?",o:["Un sonido más fuerte","El mismo patrón se repite en cada par de cuerdas","Es más fácil de afinar","Menos cuerdas"],w:"El patrón se conserva, así que solo hay que aprenderlo una vez."},
5:"Toca la escala en dos octavas, diez veces."}},

"mandolin-8":{title:"Melodía con acompañamiento",goal:"Tocar una canción entera e intercalar acordes",b:{
0:"Ahora se combina: melodía, acordes y trémolo en la misma pieza.",
1:"Pieza combinada",
2:"Toca primero solo la melodía, luego solo los acordes y solo entonces combina. Combinar demasiado pronto estropea ambas cosas.",
3:{q:"¿Cómo se combinan melodía y acompañamiento?",o:["Tocándolos juntos desde el principio","Aprendiendo cada uno por separado y luego combinando","Renunciando a uno de los dos","Tocando muy despacio"],w:"Separar primero y combinar después: ese es el camino rápido."},
4:"Toca la pieza combinada cinco veces."}},

"mandolin-9":{title:"Resumen y qué viene después",goal:"Saber qué has aprendido y hacia dónde ir",b:{
0:"Has terminado: cuerdas al aire, notas en el mástil, acordes, trémolo y escalas en dos octavas.",
1:"Qué viene después: el <b>estilo bluegrass</b> (púa rápida y precisa), los <b>acordes cerrados</b> que se desplazan por el mástil y la <b>improvisación</b> sobre las escalas aprendidas.",
2:"Pieza final",
3:"La mandolina comparte afinación con el violín: todo lo aprendido aquí se transfiere casi por completo si alguna vez quieres probarlo.",
4:{q:"¿Qué instrumento comparte la afinación de la mandolina?",o:["La guitarra","El violín","El bajo","El ukelele"],w:"Ambos se afinan sol-re-la-mi."},
5:"Toca la pieza final y grábate."}}

});
